authors.example:
extend schema
  @link(url: "https://specs.graphql-mesh.dev/core/v0.1", import: ["@transport"])
  @transport(
    subgraph: "shop"
    kind: "sql"
    location: "postgres://localhost/shop"
  )

type User @source(name: "User_users", subgraph: "users") {
  id: ID! @source(name: "id", subgraph: "users")
}

type Query {
  user(id: ID!): User @merge(keyField: "id", keyArg: "id", subgraph: "users")
  users(ids: [ID!]!): [User!]! @merge(keyField: "id", keyArg: "ids", subgraph: "users")
}

type User {
  repositories: [Repository]
    @resolveTo(
      sourceName: "A"
      sourceTypeName: "Query"
      sourceFieldName: "repositoriesByUserId"
      requiredSelectionSet: "{ id }"
      sourceArgs: { id: "{root.id}" }
    )
}
